import { useState } from 'react';
import { SuccessIcon, WarningIcon, ErrorIcon } from 'lucide-react';
import NotificationList from './NotificationList';

type Message = {
  id: string;
  type: 'success' | 'warning' | 'error';
  message: string;
  timestamp: Date;
};

export default function App() {
  const [messages, setMessages] = useState<Message[]>([]);
  const [isToastVisible, setIsToastVisible] = useState(false);

  const handleButtonClick = (type: 'success' | 'warning' | 'error') => {
    const message: Message = {
      id: Date.now().toString(),
      type,
      message: `This is a ${type} message.`,
      timestamp: new Date(),
    };

    setMessages((prev) => [message, ...prev.slice(0, 4)]); // Keep only last 5
    setIsToastVisible(true);

    // Hide toast after 3 seconds
    setTimeout(() => setIsToastVisible(false), 3000);
  };

  const handleClear = () => {
    setMessages([]);
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col items-center p-6">
      <div className="w-full max-w-3xl bg-white rounded-lg shadow-md p-6 space-y-6">
        <h1 className="text-2xl font-bold text-gray-800">Notification Center</h1>

        <div className="flex flex-wrap gap-3 justify-center">
          <button
            onClick={() => handleButtonClick('success')}
            className="flex items-center gap-2 px-4 py-2 bg-green-500 text-white rounded-md hover:bg-green-600 transition-colors"
          >
            <SuccessIcon className="w-5 h-5" />
            Success
          </button>

          <button
            onClick={() => handleButtonClick('warning')}
            className="flex items-center gap-2 px-4 py-2 bg-yellow-500 text-white rounded-md hover:bg-yellow-600 transition-colors"
          >
            <WarningIcon className="w-5 h- tqdm" />
            Warning
          </button>

          <button
            onClick={() => handleButtonClick('error')}
            className="flex items-center gap-2 px-4 py-2 bg-red-500 text-white rounded-md hover:bg-red-600 transition-colors"
          >
            <ErrorIcon className="w-5 h-5" />
            Error
          </button>
        </div>

        <NotificationList messages={messages} onClear={handleClear} />
      </div>
    </div>
  );
}
```

