### NotificationList.tsx
```tsx
import { useState } from 'react';
import { ClearIcon } from 'lucide-react';

type Message = {
  id: string;
  type: 'success' | 'warning' | 'error';
  message: string;
  timestamp: Date;
};

type Props = {
  messages: Message[];
  onClear: () => void;
};

export default function NotificationList({ messages, onClear }: Props) {
  if (messages.length === 0) {
    return (
      <div className="py-4 text-center text-gray-500">
        No messages yet. Click a button to see a toast.
      </div>
    );
  }

  return (
    <div className="border-t pt-4">
      <div className="flex justify-between items-center mb-2">
        <h2 className="text-lg font-semibold text-gray-700">Recent Messages</h2>
        <button
          onClick={onClear}
          className="flex items-center gap-1 text-sm text-red-600 hover:text-red-800 transition-colors"
        >
          <ClearIcon className="w-4 h-4" />
          Clear All
        </button>
      </div>
      <ul className="space-y-2 max-h-60 overflow-y-auto">
        {messages.map((msg) => (
          <li
            key={msg.id}
            className={`p-3 rounded-md flex items-start gap-3 ${
              msg.type === 'success'
                ? 'bg-green-50 text-green-800'
                : msg.type === 'warning'
                ? 'bg-yellow-50 text-yellow-800'
                : 'bg-red-50 text-red-800'
            }`}
          >
            <div className="flex-shrink-0 mt-1">
              {msg.type === 'success' && <span className="w-3 h-3 bg-green-500 rounded-full"></span>}
              {msg.type === 'warning' && <span className="w-3 h-3 bg-yellow-500 rounded-full"></span>}
              {msg.type === 'error' && <span className="w-3 h-3 bg-red-500 rounded-full"></span>}
            </div>
            <div className="flex-1">
              <p className="text-sm font-medium">{msg.message}</p>
              <p className="text-xs mt-1 opacity-75">
                {new Date(msg.timestamp).toLocaleString()}
              </p>
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
}
